import random
import struct
import io

# We need to generate a file buffer that will be consumed by CPLFGets(),
# which reads up to nBufferSize-1 bytes or until a newline, and NUL-terminates.
# Interesting cases include different newline styles, very long lines, empty lines,
# non-text binary data, no newline at EOF, lines exactly at boundary sizes, and
# various encodings / byte patterns. Keep size <= 4096 bytes.

MAX_SIZE = 4096


def _rand_choice(rng, seq):
    return seq[rng.randrange(0, len(seq))]


def _make_newline_variants(rng):
    # Include Unix, Windows, old Mac, mixed, and no newline
    choices = [b"\n", b"\r\n", b"\r", b"\n\r", b"", b"\x00\n", b"\n\x00"]
    return _rand_choice(rng, choices)


def _make_text_line(rng, min_len=0, max_len=512, include_utf8=True):
    length = rng.randrange(min_len, max_len + 1)
    # Mix of ASCII printable, tabs/spaces, and optionally some UTF-8 multibyte.
    parts = []
    while sum(len(p) for p in parts) < length:
        mode = rng.random()
        if include_utf8 and mode < 0.15:
            # insert a random valid UTF-8 sequence (2-3 bytes typical)
            # pick from a small set of common multibyte chars
            utf8_choices = [
                "é", "€", "漢", "✓", "—", "Ω", "µ", "ß", "ñ", "Á",
            ]
            b = _rand_choice(rng, utf8_choices).encode("utf-8")
            parts.append(b)
        elif mode < 0.85:
            # printable ASCII
            ch = rng.randrange(0x20, 0x7F)
            parts.append(bytes([ch]))
        else:
            # whitespace variety excluding newline
            parts.append(_rand_choice(rng, [b" ", b"\t", b"\v", b"\f"]))
    data = b"".join(parts)
    return data[:length]


def _make_binary_chunk(rng, size):
    # Include a mix of random bytes with occasional NULs and 0xFF
    out = bytearray()
    for _ in range(size):
        mode = rng.random()
        if mode < 0.05:
            out.append(0)
        elif mode < 0.10:
            out.append(0xFF)
        elif mode < 0.15:
            out.append(rng.randrange(0x01, 0x20))  # control chars excluding NUL
        else:
            out.append(rng.randrange(0x20, 0x100))
    return bytes(out)


def _gen_case_long_first_line(rng):
    # Create a very long first line without newline to stress size limits.
    line_len = rng.randrange(600, 1200)
    line = _make_text_line(rng, line_len, line_len, include_utf8=True)
    rest = b"" if rng.random() < 0.5 else b"\nSecond line\n"
    return line + rest


def _gen_case_many_short_lines(rng):
    # Many short lines, including empty ones and various newline styles
    buf = io.BytesIO()
    count = rng.randrange(5, 40)
    for i in range(count):
        if rng.random() < 0.2:
            line = b""  # empty line
        else:
            line = _make_text_line(rng, 0, rng.randrange(1, 40))
        nl = _make_newline_variants(rng)
        buf.write(line + nl)
    return buf.getvalue()


def _gen_case_mixed_binary_and_text(rng):
    buf = io.BytesIO()
    # Start with a text line
    buf.write(_make_text_line(rng, 5, 80) + _rand_choice(rng, [b"\n", b"\r\n"]))
    # Then binary chunk containing internal newlines and NULs
    bin_size = rng.randrange(50, 300)
    bin_chunk = _make_binary_chunk(rng, bin_size)
    buf.write(bin_chunk)
    # Maybe end with newline or not
    if rng.random() < 0.6:
        buf.write(_make_newline_variants(rng))
    # Followed by another ASCII line
    if rng.random() < 0.8:
        buf.write(_make_text_line(rng, 0, 60) + _rand_choice(rng, [b"\n", b"\r\n", b""]))
    return buf.getvalue()


def _gen_case_boundary_aligned(rng):
    # Produce lines around common buffer boundaries used by stub (1..512)
    # We create sequences with lines lengths 1, 2, 3, 7, 15, 31, 63, 127, 255, 511
    lines = []
    for target in [1, 2, 3, 7, 15, 31, 63, 127, 255, 511]:
        ln = min(target, 100)  # keep individual lines moderate; still interesting
        line = _make_text_line(rng, ln, ln, include_utf8=False)
        nl = _rand_choice(rng, [b"\n", b"\r\n"]) if target % 2 == 0 else b"\n"
        lines.append(line + nl)
    return b"".join(lines)


def _gen_case_no_newlines(rng):
    # Entire buffer without any newline, may contain NULs
    size = rng.randrange(1, 1024)
    if rng.random() < 0.5:
        return _make_text_line(rng, size, size, include_utf8=False).replace(b"\n", b"")
    else:
        return _make_binary_chunk(rng, size).replace(b"\n", b"")


def _trim_to_max(data: bytes) -> bytes:
    if len(data) <= MAX_SIZE:
        return data
    # Ensure we don't cut in the middle of a \r\n pair in a trivial attempt
    cut = MAX_SIZE
    if cut > 0 and data[cut-1:cut+1] == b"\r\n":
        cut -= 1
    return data[:cut]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a scenario
    scenario_funcs = [
        _gen_case_long_first_line,
        _gen_case_many_short_lines,
        _gen_case_mixed_binary_and_text,
        _gen_case_boundary_aligned,
        _gen_case_no_newlines,
    ]
    # Weighted to favor diverse line structures
    weights = [0.2, 0.25, 0.25, 0.2, 0.1]
    # Python's random doesn't have choices with weights pre-3.6 uniformly across, implement manually
    x = rng.random()
    cumulative = 0.0
    pick = scenario_funcs[-1]
    for f, w in zip(scenario_funcs, weights):
        cumulative += w
        if x <= cumulative:
            pick = f
            break
    data = pick(rng)

    # Occasionally prepend BOMs or metadata to exercise start-of-file parsing
    if rng.random() < 0.2:
        bom = _rand_choice(rng, [b"\xEF\xBB\xBF", b"\xFF\xFE", b"\xFE\xFF"])  # UTF-8/UTF-16 BOMs
        data = bom + data

    # Occasionally append a final partial line token without newline
    if rng.random() < 0.3:
        tail = _make_text_line(rng, 0, rng.randrange(1, 40))
        data += tail

    # Ensure non-empty and within size
    if not data:
        data = b"\n"

    return _trim_to_max(data)
